package com.smartfile.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="applications",indexes={@Index(name="idx_app_status",columnList="status"),@Index(name="idx_app_file_id",columnList="fileId",unique=true)}) public class SmartApplication { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false,unique=true) public String fileId; @Column(nullable=false) public String applicationType; @Column(nullable=false) public String applicantName; @ManyToOne(fetch=FetchType.EAGER) public Department department; @Column(nullable=false) public String status="Submitted"; public String priority="Normal"; public String assignedOfficer; public Instant submittedAt=Instant.now(); public Instant deadline; public String currentStage="Clerk verification"; public SmartApplication(){} }
